/**
 * 1. 更新 visual_chart_element 新增 name state 字段
 * 2. 备份并更新 visual_chart
 * 3. 导入 内置 overview panel & 初始化chart
 */

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

ALTER TABLE `visual_chart_element`
ADD COLUMN `name` varchar(64) NOT NULL DEFAULT '' COMMENT '默认："" 初始化按照 每个chart数据  A-Z 顺序添加',
ADD COLUMN `state` char(1) NOT NULL DEFAULT '1' COMMENT '默认： 1';

-- 复制表结构
CREATE TABLE visual_chart_V3_2 like visual_chart;

-- 复制表数据
INSERT INTO visual_chart_V3_2 select * from visual_chart;

-- 删除原来数据
DELETE FROM visual_chart;

-- 更新 visual_chart 表结构
ALTER TABLE `visual_chart` 
ADD COLUMN `datasource` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '数据源 1：metrics\r\n2：logs\r\n3：system\r\n4：misc' ;


-- 导入内置 overview panel
UPDATE `visual_panel` SET weight = (weight + 1) WHERE type='dashboard' and pid = 0;
INSERT INTO `visual_panel`(`id`, `name`, `create_by`, `type`, `link`, `pid`, `weight`, `build_in`, `seq`) VALUES (NULL, 'Overview', 1, 'dashboard', 0, 0, 0, '1', 'v3.2-buildin');

-- 获取 overview panel id
SELECT @panelId:=id FROM visual_panel WHERE seq = 'v3.2-buildin';

-- 导入 overview 初始化chart
